// hidden is `p` without the entries the schema said are never answered with,
// or nil when there is nothing left to say.
//
// It is the redactor of every copy of a write that leaves the write -- the
// trail's, the outbox's and the in-process publish's -- and what it takes
// out is a `secret:` and nothing else. The trail takes a `personal:` field
// out as well, and does that itself: the outbox and the publish carry the
// row they are about, which whoever may read the row reads the person in.
func hidden(key pdid.Id, p *patchpb.Patch) *patchpb.Patch {
	_, secret, _ := described(key)

	return audit.Withhold(p, secret)
}

// added is whether `by`, the write a server made, made a row: an Add, or an
// AddMany's for one of its items. See `bare.Change.By`.
func added(by string) bool {
	switch by {
	case api.AddressPolicyService_Add_FullMethodName,
		api.AttemptService_Add_FullMethodName,
		api.AuditService_Add_FullMethodName,
		api.DelegationService_Add_FullMethodName,
		api.DeviceService_Add_FullMethodName,
		api.HolderService_Add_FullMethodName,
		api.LaminaService_Add_FullMethodName,
		api.NodeService_Add_FullMethodName,
		api.PlacementPolicyService_Add_FullMethodName,
		api.ProducerService_Add_FullMethodName,
		api.ReaderService_Add_FullMethodName,
		api.RelayService_Add_FullMethodName,
		api.SetService_Add_FullMethodName,
		api.SigningKeyService_Add_FullMethodName,
		api.SinkService_Add_FullMethodName,
		api.SiteService_Add_FullMethodName,
		api.SiteMemberService_Add_FullMethodName,
		api.SourceService_Add_FullMethodName,
		api.TenantService_Add_FullMethodName,
		api.UploadPolicyService_Add_FullMethodName:
		return true
	}

	return false
}

// subject is the tenant of `row`, the row `key` names as the write left it,
// and what the trail keeps of it; the nil identifier when there is no row
// any more -- an erase that took it, which the caller files under the
// actor's tenant.
//
// The row is answered with only when `keep` says the trail keeps it, which
// is the `value` content level, and then without what the entity declared
// `secret` or `personal`; otherwise the bytes are empty, and the row is
// read for its tenant alone. It is not changed: it is the write's, handed
// to every recorder, and the digest of it is made after this.
func subject(ctx context.Context, s bare.Server, key pdid.Id, image proto.Message, keep bool) (uuid.UUID, []byte, error) {
	switch key.Domain() {
	case AccessDomain:
		row, ok := image.(*api.Access)
		if !ok {
			return uuid.Nil(), []byte{}, nil
		}

		b := []byte{}
		if keep {
			kept := row
			v, err := proto.Marshal(kept)
			if err != nil {
				return uuid.Nil(), nil, err
			}
			b = v
		}

		k, err := entuuid.FromBytes(row.GetTenantId())
		if err != nil {
			return uuid.Nil(), nil, err
		}

		return k, b, nil

	case AttemptDomain:
		row, ok := image.(*api.Attempt)
		if !ok {
			return uuid.Nil(), []byte{}, nil
		}

		b := []byte{}
		if keep {
			kept := row
			v, err := proto.Marshal(kept)
			if err != nil {
				return uuid.Nil(), nil, err
			}
			b = v
		}

		if !row.HasTenant() {
			return uuid.Nil(), b, nil
		}

		k, err := entuuid.FromBytes(row.GetTenant().GetId())
		if err != nil {
			return uuid.Nil(), nil, err
		}

		return k, b, nil

	case AuditDomain:
		row, ok := image.(*api.Audit)
		if !ok {
			return uuid.Nil(), []byte{}, nil
		}

		b := []byte{}
		if keep {
			kept := row
			v, err := proto.Marshal(kept)
			if err != nil {
				return uuid.Nil(), nil, err
			}
			b = v
		}

		k, err := entuuid.FromBytes(row.GetTenantId())
		if err != nil {
			return uuid.Nil(), nil, err
		}

		return k, b, nil

	case DelegationDomain:
		row, ok := image.(*api.Delegation)
		if !ok {
			return uuid.Nil(), []byte{}, nil
		}

		b := []byte{}
		if keep {
			kept := row
			kept = proto.Clone(row).(*api.Delegation)
			_, secret, personal := described(key)
			audit.Clear(kept, secret)
			audit.Clear(kept, personal)

			v, err := proto.Marshal(kept)
			if err != nil {
				return uuid.Nil(), nil, err
			}
			b = v
		}

		if !row.HasTenant() {
			return uuid.Nil(), b, nil
		}

		k, err := entuuid.FromBytes(row.GetTenant().GetId())
		if err != nil {
			return uuid.Nil(), nil, err
		}

		return k, b, nil

	case HolderDomain:
		row, ok := image.(*api.Holder)
		if !ok {
			return uuid.Nil(), []byte{}, nil
		}

		b := []byte{}
		if keep {
			kept := row
			kept = proto.Clone(row).(*api.Holder)
			_, secret, personal := described(key)
			audit.Clear(kept, secret)
			audit.Clear(kept, personal)

			v, err := proto.Marshal(kept)
			if err != nil {
				return uuid.Nil(), nil, err
			}
			b = v
		}

		if !row.HasTenant() {
			return uuid.Nil(), b, nil
		}

		k, err := entuuid.FromBytes(row.GetTenant().GetId())
		if err != nil {
			return uuid.Nil(), nil, err
		}

		return k, b, nil

	case LaminaDomain:
		row, ok := image.(*api.Lamina)
		if !ok {
			return uuid.Nil(), []byte{}, nil
		}

		b := []byte{}
		if keep {
			kept := row
			v, err := proto.Marshal(kept)
			if err != nil {
				return uuid.Nil(), nil, err
			}
			b = v
		}

		if !row.HasTenant() {
			return uuid.Nil(), b, nil
		}

		k, err := entuuid.FromBytes(row.GetTenant().GetId())
		if err != nil {
			return uuid.Nil(), nil, err
		}

		return k, b, nil

	case ProducerDomain:
		row, ok := image.(*api.Producer)
		if !ok {
			return uuid.Nil(), []byte{}, nil
		}

		b := []byte{}
		if keep {
			kept := row
			v, err := proto.Marshal(kept)
			if err != nil {
				return uuid.Nil(), nil, err
			}
			b = v
		}

		if !row.HasTenant() {
			return uuid.Nil(), b, nil
		}

		k, err := entuuid.FromBytes(row.GetTenant().GetId())
		if err != nil {
			return uuid.Nil(), nil, err
		}

		return k, b, nil

	case ReaderDomain:
		row, ok := image.(*api.Reader)
		if !ok {
			return uuid.Nil(), []byte{}, nil
		}

		b := []byte{}
		if keep {
			kept := row
			v, err := proto.Marshal(kept)
			if err != nil {
				return uuid.Nil(), nil, err
			}
			b = v
		}

		if !row.HasTenant() {
			return uuid.Nil(), b, nil
		}

		k, err := entuuid.FromBytes(row.GetTenant().GetId())
		if err != nil {
			return uuid.Nil(), nil, err
		}

		return k, b, nil

	case SetDomain:
		row, ok := image.(*api.Set)
		if !ok {
			return uuid.Nil(), []byte{}, nil
		}

		b := []byte{}
		if keep {
			kept := row
			v, err := proto.Marshal(kept)
			if err != nil {
				return uuid.Nil(), nil, err
			}
			b = v
		}

		if !row.HasTenant() {
			return uuid.Nil(), b, nil
		}

		k, err := entuuid.FromBytes(row.GetTenant().GetId())
		if err != nil {
			return uuid.Nil(), nil, err
		}

		return k, b, nil

	case SiteDomain:
		row, ok := image.(*api.Site)
		if !ok {
			return uuid.Nil(), []byte{}, nil
		}

		b := []byte{}
		if keep {
			kept := row
			v, err := proto.Marshal(kept)
			if err != nil {
				return uuid.Nil(), nil, err
			}
			b = v
		}

		if !row.HasTenant() {
			return uuid.Nil(), b, nil
		}

		k, err := entuuid.FromBytes(row.GetTenant().GetId())
		if err != nil {
			return uuid.Nil(), nil, err
		}

		return k, b, nil

	case SiteMemberDomain:
		row, ok := image.(*api.SiteMember)
		if !ok {
			return uuid.Nil(), []byte{}, nil
		}

		b := []byte{}
		if keep {
			kept := row
			v, err := proto.Marshal(kept)
			if err != nil {
				return uuid.Nil(), nil, err
			}
			b = v
		}

		if !row.HasTenant() {
			return uuid.Nil(), b, nil
		}

		k, err := entuuid.FromBytes(row.GetTenant().GetId())
		if err != nil {
			return uuid.Nil(), nil, err
		}

		return k, b, nil

	case SourceDomain:
		row, ok := image.(*api.Source)
		if !ok {
			return uuid.Nil(), []byte{}, nil
		}

		b := []byte{}
		if keep {
			kept := row
			v, err := proto.Marshal(kept)
			if err != nil {
				return uuid.Nil(), nil, err
			}
			b = v
		}

		if !row.HasTenant() {
			return uuid.Nil(), b, nil
		}

		k, err := entuuid.FromBytes(row.GetTenant().GetId())
		if err != nil {
			return uuid.Nil(), nil, err
		}

		return k, b, nil

	case TenantDomain:
		row, ok := image.(*api.Tenant)
		if !ok {
			return uuid.Nil(), []byte{}, nil
		}

		b := []byte{}
		if keep {
			kept := row
			v, err := proto.Marshal(kept)
			if err != nil {
				return uuid.Nil(), nil, err
			}
			b = v
		}

		k, err := entuuid.FromBytes(row.GetId())
		if err != nil {
			return uuid.Nil(), nil, err
		}

		return k, b, nil

	}

	// An entity with no tenant to file under: one declared `global: {}`,
	// which the switch above skips, or a domain nothing registered, which
	// is an identifier from somewhere else. Nothing to read either way.
	return uuid.Nil(), []byte{}, nil
}

// left is the row a write left of the thing `key` names: `image`, the one
// it handed over, or the row there is now when it handed none -- an
// Erase's, read as a check of the rows reads it, erased softly or not --
// and nil for a write that left none: an erase that took the row with it.
func left(ctx context.Context, s bare.Server, key pdid.Id, image proto.Message) (proto.Message, error) {
	if image != nil && image.ProtoReflect().IsValid() {
		return image, nil
	}

	var vs []audit.Live
	var err error
	switch key.Domain() {
	case AddressPolicyDomain:
		vs, err = rowsAddressPolicy(ctx, s.Db, entAddressPolicy.IdEQ(uuid.UUID(key)))
	case AttemptDomain:
		vs, err = rowsAttempt(ctx, s.Db, entAttempt.IdEQ(uuid.UUID(key)))
	case DelegationDomain:
		vs, err = rowsDelegation(ctx, s.Db, entDelegation.IdEQ(uuid.UUID(key)))
	case DeviceDomain:
		vs, err = rowsDevice(ctx, s.Db, entDevice.IdEQ(uuid.UUID(key)))
	case HolderDomain:
		vs, err = rowsHolder(ctx, s.Db, entHolder.IdEQ(uuid.UUID(key)))
	case LaminaDomain:
		vs, err = rowsLamina(ctx, s.Db, entLamina.IdEQ(uuid.UUID(key)))
	case NodeDomain:
		vs, err = rowsNode(ctx, s.Db, entNode.IdEQ(uuid.UUID(key)))
	case PlacementPolicyDomain:
		vs, err = rowsPlacementPolicy(ctx, s.Db, entPlacementPolicy.IdEQ(uuid.UUID(key)))
	case ProducerDomain:
		vs, err = rowsProducer(ctx, s.Db, entProducer.IdEQ(uuid.UUID(key)))
	case ReaderDomain:
		vs, err = rowsReader(ctx, s.Db, entReader.IdEQ(uuid.UUID(key)))
	case RelayDomain:
		vs, err = rowsRelay(ctx, s.Db, entRelay.IdEQ(uuid.UUID(key)))
	case SetDomain:
		vs, err = rowsSet(ctx, s.Db, entSet.IdEQ(uuid.UUID(key)))
	case SigningKeyDomain:
		vs, err = rowsSigningKey(ctx, s.Db, entSigningKey.IdEQ(uuid.UUID(key)))
	case SinkDomain:
		vs, err = rowsSink(ctx, s.Db, entSink.IdEQ(uuid.UUID(key)))
	case SiteDomain:
		vs, err = rowsSite(ctx, s.Db, entSite.IdEQ(uuid.UUID(key)))
	case SiteMemberDomain:
		vs, err = rowsSiteMember(ctx, s.Db, entSiteMember.IdEQ(uuid.UUID(key)))
	case SourceDomain:
		vs, err = rowsSource(ctx, s.Db, entSource.IdEQ(uuid.UUID(key)))
	case TenantDomain:
		vs, err = rowsTenant(ctx, s.Db, entTenant.IdEQ(uuid.UUID(key)))
	case UploadPolicyDomain:
		vs, err = rowsUploadPolicy(ctx, s.Db, entUploadPolicy.IdEQ(uuid.UUID(key)))
	default:
		return nil, nil
	}
	if err != nil || len(vs) == 0 {
		return nil, err
	}

	return vs[0].Row, nil
}

// line is the line of the trail a write is about to be recorded as, decided
// before it is written so that the digest it keeps can be bound to it
// (payday#115): its key, as the servers mint one for the trail, and its
// moment by their clock, to the microsecond every database keeps.
func line(s bare.Server, action string) audit.Line {
	at := time.Now()
	if s.Now != nil {
		at = s.Now()
	}

	return audit.Line{
		Id:      pdid.New(AuditDomain),
		Created: at.UTC().Truncate(time.Microsecond),
		Action:  action,
	}
}

// digested is the digest the line `at` keeps of `row`, the row a write left
// of the thing `key` names, and the fields it covers: empty for a
// deployment that keeps none, and of the line alone for a write that left
// no row (payday#115) -- and what the write does to the row's seal, nil
// for a kind that declares no field `personal`.
//
// What the digest covers is the entity's fields less the ones it declared
// `personal`, which it leaves out however the row it is handed was read:
// the line that keeps it outlives the row, in the archive, and the person.
// A field declared `secret` is covered, since a keyed MAC of a verifier is
// neither a copy of it nor a way to test a guess at it without the key. The
// seal covers every field, the personal ones among them, and lives beside
// the row for as long as it does; a write that took the row removes it.
func digested(d *audit.Digest, key pdid.Id, row proto.Message, at audit.Line) ([]byte, []uint32, *rowSeal, error) {
	md, _, personal := described(key)
	switch {
	case d == nil || md == nil:
		return []byte{}, []uint32{}, nil, nil
	case row == nil:
		var gone *rowSeal
		if isSealed(key) {
			gone = &rowSeal{object: key, gone: true}
		}

		return d.Gone(key, at), []uint32{}, gone, nil
	}

	covered := audit.Covered(md, personal)
	if isSealed(key) {
		all := audit.Covered(md, nil)
		sum, sealSum, err := d.OfSealed(key, row, covered, all, at)
		if err != nil {
			return nil, nil, nil, err
		}

		return sum, covered, &rowSeal{object: key, sum: sealSum, fields: all}, nil
	}

	sum, err := d.Of(key, row, covered, at)
	if err != nil {
		return nil, nil, nil, err
	}

	return sum, covered, nil, nil
}

// keptTrail is the trail a transaction has recorded and not written yet.
//
// It is kept by the transaction ([dialect.Keep]) and written by its commit,
// or a few hundred rows at a time before that, or ahead of any statement
// about the trail the transaction sends. The commit is what writes it, so
// a transaction cannot be ended with any of it left out, and one rolled
// back takes it along unwritten.
type keptTrail struct {
	// db is the client of the first write the transaction recorded, which
	// is as good as any other's: every one of them is that transaction.
	db   *ent.Client
	rows []*ent.AuditCreate

	// writing is the rows being written, by a statement that is itself
	// about the trail: asked to write them first, it finds them on the way.
	writing bool
}

// keptTrailKey is what a transaction keeps its [keptTrail] under.
type keptTrailKey struct{}

// keptTrailRows is how many rows of the trail one statement writes.
const keptTrailRows = 500

// keptTrailAbout is whether a statement is about the trail: the table's
// name as a word of it. Every statement that is about it has what is kept
// written first, so that it finds every row the transaction recorded.
var keptTrailAbout = regexp.MustCompile(`\b` + regexp.QuoteMeta(entAudit.Table) + `\b`).MatchString

func keptTrailOf(k *dialect.Keep, db *ent.Client) *keptTrail {
	return k.Value(keptTrailKey{}, func() any {
		v := &keptTrail{db: db}
		k.BeforeCommit(v.write)
		k.BeforeStatement(keptTrailAbout, v.write)
		return v
	}).(*keptTrail)
}

func (v *keptTrail) add(ctx context.Context, q *ent.AuditCreate) error {
	v.rows = append(v.rows, q)
	if len(v.rows) < keptTrailRows {
		return nil
	}

	return v.write(ctx)
}

// write writes what is kept, a statement for each few hundred rows.
func (v *keptTrail) write(ctx context.Context) error {
	if v.writing {
		return nil
	}
	v.writing = true
	defer func() { v.writing = false }()

	for len(v.rows) > 0 {
		n := min(len(v.rows), keptTrailRows)
		if err := v.db.Audit.CreateBulk(v.rows[:n]...).Exec(ctx); err != nil {
			return fmt.Errorf("write the trail: %w", err)
		}
		v.rows = v.rows[n:]
	}

	return nil
}

// isSealed is whether rows of `key`'s kind are sealed: it is on the trail and
// declares a field `personal`, which the trail's digest leaves out and the
// row's seal covers (payday#115).
func isSealed(key pdid.Id) bool {
	switch key.Domain() {
	case HolderDomain:
		return true
	}

	return false
}

// rowSeal is what a write does to the seal of one row: writes `sum`, over the
// fields `fields` lists, filed under `tenant` -- or, `gone`, removes it, for
// a write that took the row.
type rowSeal struct {
	object pdid.Id
	tenant uuid.UUID
	sum    []byte
	fields []uint32
	gone   bool
}

// in is `v` filed under `tenant`: where the write that made it filed its
// line. Nil for nil, which is a write that does nothing to a seal.
func (v *rowSeal) in(tenant uuid.UUID) *rowSeal {
	if v == nil {
		return nil
	}

	c := *v
	c.tenant = tenant
	return &c
}

// keepSeals does what `vs` say to the seals of their rows, in the transaction `db`
// runs in: kept for its commit when it keeps anything, as the trail is, and
// written now when it does not. A nil of `vs` is a write that does nothing
// to a seal.
func keepSeals(ctx context.Context, db *ent.Client, vs ...*rowSeal) error {
	vs = slices.DeleteFunc(vs, func(v *rowSeal) bool { return v == nil })
	if len(vs) == 0 {
		return nil
	}
	if k, ok := dialect.KeepOf(db.Driver()); ok {
		return keptSealsOf(k, db).add(ctx, vs)
	}

	return writeSeals(ctx, db, vs)
}

// keptSeals is the seals a transaction has written and not yet sent, kept by
// it ([dialect.Keep]) and written by its commit, a few hundred at a time
// before that, or ahead of any statement about the table -- as [keptTrail]
// is, and for the same reasons.
type keptSeals struct {
	db      *ent.Client
	vs      []*rowSeal
	writing bool
}

// keptSealsKey is what a transaction keeps its [keptSeals] under.
type keptSealsKey struct{}

// keptSealsAbout is whether a statement is about the seals: the table's
// name as a word of it.
var keptSealsAbout = regexp.MustCompile(`\b` + regexp.QuoteMeta(entRowSeal.Table) + `\b`).MatchString

func keptSealsOf(k *dialect.Keep, db *ent.Client) *keptSeals {
	return k.Value(keptSealsKey{}, func() any {
		v := &keptSeals{db: db}
		k.BeforeCommit(v.write)
		k.BeforeStatement(keptSealsAbout, v.write)
		return v
	}).(*keptSeals)
}

func (v *keptSeals) add(ctx context.Context, vs []*rowSeal) error {
	v.vs = append(v.vs, vs...)
	if len(v.vs) < keptSealsRows {
		return nil
	}

	return v.write(ctx)
}

func (v *keptSeals) write(ctx context.Context) error {
	if v.writing || len(v.vs) == 0 {
		return nil
	}
	v.writing = true
	defer func() { v.writing = false }()

	vs := v.vs
	v.vs = nil

	return writeSeals(ctx, v.db, vs)
}

// keptSealsRows is how many seals one statement writes.
const keptSealsRows = 500

// writeSeals sends what `vs` say: the last word about each row, the seals in
// an INSERT that writes over the seal there is, a few hundred a statement,
// and the seals of rows that went in one DELETE.
func writeSeals(ctx context.Context, db *ent.Client, vs []*rowSeal) error {
	last := map[pdid.Id]*rowSeal{}
	order := []pdid.Id{}
	for _, v := range vs {
		if _, ok := last[v.object]; !ok {
			order = append(order, v.object)
		}
		last[v.object] = v
	}

	put := []*rowSeal{}
	gone := []uuid.UUID{}
	for _, k := range order {
		if v := last[k]; v.gone {
			gone = append(gone, uuid.UUID(k))
		} else {
			put = append(put, v)
		}
	}

	drv := db.Driver()
	for page := range slices.Chunk(put, keptSealsRows) {
		q := sql.Dialect(drv.Dialect()).Insert(entRowSeal.Table).
			Columns(entRowSeal.FieldId, entRowSeal.FieldTenantId, entRowSeal.FieldSum, entRowSeal.FieldFields)
		for _, v := range page {
			fields, err := json.Marshal(v.fields)
			if err != nil {
				return err
			}
			q.Values(uuid.UUID(v.object), v.tenant, v.sum, json.RawMessage(fields))
		}
		q.OnConflict(sql.ConflictColumns(entRowSeal.FieldId), sql.ResolveWithNewValues())

		query, args := q.Query()
		var res sql1.Result
		if err := drv.Exec(ctx, query, args, &res); err != nil {
			return fmt.Errorf("write the seals: %w", err)
		}
	}
	for page := range slices.Chunk(gone, keptSealsRows) {
		if _, err := db.RowSeal.Delete().Where(entRowSeal.IdIn(page...)).Exec(ctx); err != nil {
			return fmt.Errorf("remove the seals: %w", err)
		}
	}

	return nil
}

// carrySeals binds the seals of the rows a pass carried a line forward for
// to the lines it wrote ([audit.Digest.CarrySeal]): what each said of its
// row, copied, and bound to the new line. A row with no seal has none to
// carry.
func carrySeals(ctx context.Context, db *ent.Client, d *audit.Digest, lines map[pdid.Id]audit.Line, tenants map[pdid.Id]uuid.UUID) error {
	if len(lines) == 0 {
		return nil
	}

	seals, err := sealsOf(ctx, db, slices.Collect(maps.Keys(lines)))
	if err != nil {
		return err
	}

	vs := make([]*rowSeal, 0, len(seals))
	for id, v := range seals {
		sum, err := d.CarrySeal(v.Sum, id, lines[id])
		if err != nil {
			return fmt.Errorf("carry the seal of %s forward: %w", id, err)
		}
		vs = append(vs, &rowSeal{object: id, tenant: tenants[id], sum: sum, fields: v.Fields})
	}

	return writeSeals(ctx, db, vs)
}

// sealsOf is the seal of each of `ids` that has one, as a check of the rows
// reads it.
func sealsOf(ctx context.Context, db *ent.Client, ids []pdid.Id) (map[pdid.Id]audit.Sealed, error) {
	out := map[pdid.Id]audit.Sealed{}
	if len(ids) == 0 {
		return out, nil
	}

	vs, err := db.RowSeal.Query().Where(entRowSeal.IdIn(uuids(ids)...)).All(ctx)
	if err != nil {
		return nil, err
	}
	for _, v := range vs {
		out[pdid.Id(v.Id)] = audit.Sealed{Sum: v.Sum, Fields: v.Fields}
	}

	return out, nil
}

// Digests checks every row of every kind on the trail -- every kind but the
// ones kept off it -- against the trail (payday#102, #108, #115): each
// digested again, as a Get reads it, and compared with the digest the newest
// line of the trail about it keeps -- in the database, or in the archive `p`
// names once it has left. A row somebody changed past the servers is one that
// differs, a row somebody added past them is one nothing on the trail is
// about, and a row somebody removed past them is a thing the trail says is a
// row and is not. The kinds it does not read are in what it answers, with
// why, so that a check that found nothing says what it did not look at.
//
// It changes nothing. It reads a page of a kind at a time, each page with the
// trail about it in one read-only transaction, so `db` is the database and
// not a transaction. With no archive, what is not in the database is not on
// the trail.
func Digests(ctx context.Context, db *ent.Client, d *audit.Digest, p trail.Policy) (audit.Rows, error) {
	var archived audit.Archived
	if p.Archive != nil {
		n, err := p.Newest(ctx, TrailStore(db))
		if err != nil {
			return audit.Rows{}, fmt.Errorf("the archive: %w", err)
		}
		archived = archivedDigests(n)
	}

	out := audit.Rows{Skipped: []audit.Skipped{}}
	if err := audit.CheckKind(ctx, d, checkedAddressPolicy(db), archived, &out); err != nil {
		return out, fmt.Errorf("address-policy: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedAttempt(db), archived, &out); err != nil {
		return out, fmt.Errorf("attempt: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedDelegation(db), archived, &out); err != nil {
		return out, fmt.Errorf("delegation: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedDevice(db), archived, &out); err != nil {
		return out, fmt.Errorf("device: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedHolder(db), archived, &out); err != nil {
		return out, fmt.Errorf("holder: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedLamina(db), archived, &out); err != nil {
		return out, fmt.Errorf("lamina: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedNode(db), archived, &out); err != nil {
		return out, fmt.Errorf("node: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedPlacementPolicy(db), archived, &out); err != nil {
		return out, fmt.Errorf("placement-policy: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedProducer(db), archived, &out); err != nil {
		return out, fmt.Errorf("producer: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedReader(db), archived, &out); err != nil {
		return out, fmt.Errorf("reader: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedRelay(db), archived, &out); err != nil {
		return out, fmt.Errorf("relay: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedSet(db), archived, &out); err != nil {
		return out, fmt.Errorf("set: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedSigningKey(db), archived, &out); err != nil {
		return out, fmt.Errorf("signing-key: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedSink(db), archived, &out); err != nil {
		return out, fmt.Errorf("sink: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedSite(db), archived, &out); err != nil {
		return out, fmt.Errorf("site: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedSiteMember(db), archived, &out); err != nil {
		return out, fmt.Errorf("site-member: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedSource(db), archived, &out); err != nil {
		return out, fmt.Errorf("source: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedTenant(db), archived, &out); err != nil {
		return out, fmt.Errorf("tenant: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedUploadPolicy(db), archived, &out); err != nil {
		return out, fmt.Errorf("upload-policy: %w", err)
	}

	return out, nil
}

// checkedAddressPolicy is what a check of the rows reads of the address-policy kind.
